export interface User {
  id: string;
  email: string;
  name: string;
  role: 'admin' | 'member' | 'viewer';
  createdAt: Date;
  updatedAt: Date;
}

// Project
export interface Project {
  id: string;
  name: string;
  description: string | null;
  userId: string;
  companyProfileId: string | null;
  status: 'active' | 'paused' | 'archived';
  createdAt: Date;
  updatedAt: Date;
